export function componentDefaults(type){return Object.fromEntries(Object.entries(componentDefinitions[type]?.properties||{className:field('클래스','text','MyComponent'),enabled:enabled()}).map(([key,meta])=>[key,structuredClone(meta.default)]));}
export function makeSceneComponent(type,properties={},id){if(!Object.hasOwn(componentDefinitions,type))throw Error('등록되지 않은 컴포넌트: '+type);return {id:id||crypto.randomUUID(),name:type,type,properties:{...componentDefaults(type),...structuredClone(properties)}};}
export function defaultsForObject(kind){
  const types=['Transform'];if(['camera'].includes(kind))types.push('Camera');else if(['light','directionalLight','pointLight','spotLight'].includes(kind))types.push(kind==='pointLight'?'PointLight':kind==='spotLight'?'SpotLight':'DirectionalLight');else if(kind==='audio')types.push('AudioSource');else if(['sprite','character2d'].includes(kind))types.push('SpriteRenderer');else if(kind==='tilemap')types.push('TilemapRenderer');else if(!['empty','group','playerStart','controller','gameMode','gameState','playerState'].includes(kind))types.push('MeshRenderer');
  if(['cube','arch','ground','plane','model','character'].includes(kind))types.push(kind==='character'?'CapsuleCollider':'BoxCollider');if(kind==='sphere')types.push('SphereCollider');if(kind==='cylinder')types.push('CapsuleCollider');if(kind==='sprite')types.push('BoxCollider2D');if(kind==='character2d')types.push('CapsuleCollider2D','Rigidbody2D','CharacterMovement2D');if(kind==='character')types.push('Rigidbody','CharacterMovement');if(kind==='controller')types.push('PlayerController');if(['gameMode','gameState','playerState'].includes(kind))types.push({gameMode:'GameMode',gameState:'GameState',playerState:'PlayerState'}[kind]);
  const shape=kind==='ground'?{extent:[4.7,.4,4.7],center:[0,-.3,0]}:kind==='plane'?{extent:[.75,.04,.75],center:[0,.04,0]}:kind==='cube'?{center:[0,.5,0]}:kind==='sphere'?{center:[0,.6,0],radius:.6}:kind==='cylinder'?{center:[0,.6,0],radius:.45,height:1.2}:kind==='character'?{center:[0,.9,0],friction:0,frictionCombine:'min'}:kind==='character2d'?{friction:0,frictionCombine:'min'}:{};
  return types.map((type,i)=>makeSceneComponent(type,type.includes('Collider')?shape:{},'component_'+i));
}
export function objectComponents(object){return object.components??=(defaultsForObject(object.kind));}
export function addSceneComponent(object,type){const components=objectComponents(object);if(components.length>=100)throw Error('컴포넌트 제한 초과');if(['Transform','Rigidbody','Rigidbody2D','PawnMovement','CharacterMovement','CharacterMovement2D','PlayerController','GameMode','GameState','PlayerState'].includes(type)&&components.some(c=>c.type===type))throw Error('이미 있는 컴포넌트예요.');const component=makeSceneComponent(type);components.push(component);return component;}
export function enabledComponent(object,type){const c=objectComponents(object).find(c=>c.type===type&&c.properties?.enabled!==false);return c?{...componentDefaults(type),...c.properties}:null;}
const safePath=value=>typeof value==='string'&&value.length<=1000&&!value.includes('..')&&!/^(?:[a-z]+:|[/\\])/i.test(value);
export function validComponentProperties(type,values){
  if(!values||typeof values!=='object'||Array.isArray(values))return false;const definitions=componentDefinitions[type]?.properties||{className:field('클래스','text','MyComponent'),enabled:enabled()};
  const valid=Object.entries(values).every(([key,value])=>{if(!Object.hasOwn(definitions,key))return false;const meta=definitions[key];if(meta.type==='checkbox')return typeof value==='boolean';if(meta.type==='number')return Number.isFinite(value)&&value>=(meta.min??-10000)&&value<=(meta.max??10000)&&(meta.step!==1||Number.isInteger(value));if(['vec3','color'].includes(meta.type))return Array.isArray(value)&&value.length===(meta.type==='color'?4:3)&&value.every(v=>Number.isFinite(v)&&v>=(meta.min??(meta.type==='color'?0:-10000))&&v<=(meta.max??(meta.type==='color'?1:10000)));if(meta.type==='select')return meta.choices.some(choice=>(Array.isArray(choice)?choice[0]:choice)===value);return meta.type==='asset'?safePath(value):typeof value==='string'&&value.length<=200;});const p={...componentDefaults(type),...values};return valid&&(type!=='Camera'||p.near<p.far)&&(type!=='AudioSource'||p.minDistance<p.maxDistance);
}
export function validComponents(components){return Array.isArray(components)&&components.length<=100&&new Set(components.map(c=>c?.id)).size===components.length&&components.every(c=>c&&typeof c.id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(c.id)&&typeof c.name==='string'&&c.name.length<=80&&typeof c.type==='string'&&/^[a-zA-Z_][a-zA-Z0-9_]{0,79}$/.test(c.type)&&(c.properties===undefined||validComponentProperties(c.type,c.properties)));}
export function installBlueprintComponents(objects,bindings){for(const binding of bindings){const object=objects.find(o=>o.id===binding.self);if(!object)continue;const existing=objectComponents(object),used=new Set();for(const c of binding.root.components||[]){let current=existing.find(x=>x.id===c.id&&x.type===c.type&&!used.has(x))||existing.find(x=>x.type===c.type&&!used.has(x));if(current)current.properties={...componentDefaults(c.type),...current.properties,...structuredClone(c.properties||{})};else{current={...structuredClone(c),id:existing.some(x=>x.id===c.id)?crypto.randomUUID():c.id,properties:{...componentDefaults(c.type),...structuredClone(c.properties||{})}};existing.push(current);}used.add(current);current.blueprintSources??=[];if(!current.blueprintSources.some(source=>source.name===binding.root.name&&source.id===c.id))current.blueprintSources.push({name:binding.root.name,id:c.id});}}return objects;}
